def norm_url(u):
    u = u.strip()
    u = u.split("#")[0].split("?")[0]
    if u.startswith("http://"):
        u = "https://" + u[len("http://"):]
    # collapse doubled url artifact
    m = re.match(r"(https://chat\.whatsapp\.com/(?:invite/)?[A-Za-z0-9_-]+)\1", u) if False else None
    # fix doubled links like ...Xpshttps://chat.whatsapp.com/invite/Xps
    if u.count("https://chat.whatsapp.com") > 1:
        u = "https://chat.whatsapp.com/" + u.rsplit("https://chat.whatsapp.com/", 1)[1]
    return u

def code_of(u):
    u = norm_url(u)
    seg = u.rstrip("/").rsplit("/", 1)[-1]
    if seg.lower() == "invite":
        seg = u.rstrip("/").rsplit("/", 2)[-2]
    return seg

seen = pickle.load(open(os.path.join(SCRAPED, "_seen_all_codes.pkl"), "rb"))
def seen_key(s):
    s = s.strip().split("#")[0].split("?")[0]
    seg = s.rstrip("/").rsplit("/", 1)[-1]
    return seg

seen_codes = {seen_key(s) for s in seen}

out, used = [], set()
dup_within = dup_seen = bad = 0
for name, url, desc, cat in RAW:
    url = norm_url(url)
    code = code_of(url)
    if len(code) < 10:
        bad += 1; continue
    if code in used:
        dup_within += 1; continue
    if code in seen_codes:
        dup_seen += 1; continue
    used.add(code)
    out.append({"name": name, "invite": url, "desc": desc, "cat": cat, "country": "USA"})

with open(os.path.join(SCRAPED, "team222-usa.json"), "w") as f:
    json.dump(out, f, ensure_ascii=False, indent=2)
print(f"saved={len(out)} dup_within={dup_within} dup_seen={dup_seen} bad={bad}")
